from os import environ, path
from sys import version_info

from qtpy import uic
from qtpy.QtWidgets import QDialog

try:
    from PyQt5.QtCore import QT_VERSION_STR, PYQT_VERSION_STR

    qt_version = "{} / <b>Qt</b>: {}".format(PYQT_VERSION_STR, QT_VERSION_STR)
except ImportError:
    from PySide2 import __version__

    qt_version = __version__
from ta_logcollector.ver import __version__


class AboutDialog(QDialog):
    """LogCollector about dialog window."""

    def __init__(self, parent):
        """Simple initialization."""
        super(AboutDialog, self).__init__(parent)
        uic.loadUi("{}/ui/about.ui".format(path.dirname(path.abspath(__file__))), self)
        self.setup_text()

    def setup_text(self):
        """Prepare text information about Logcollector application."""
        text = self.label.text().rstrip("</body></html>")
        text += "<p><b>logcollector:</b> {}".format(__version__)
        text += "<br><b>python:</b> {0}.{1}.{2}-{3}.{4}".format(*version_info)
        qt_api = environ.get("QT_API", "pyqt5")
        text += "<br><b>{}:</b> {}</p></body></html>".format(qt_api, qt_version)
        self.label.setText(text)
